//! Cache storage implementation.

use anyhow::{Context, Result};
use sha2::{Digest, Sha256};
use std::fs;
use std::path::{Path, PathBuf};

use super::entry::CacheEntry;

/// Atomically write `data` to `dest` by writing to a temporary file in the
/// same directory and then renaming.  This prevents concurrent readers from
/// seeing a partially-written file.
fn atomic_write(dest: &Path, data: &[u8]) -> Result<()> {
    // Build temp path in the same directory so rename is always on the same filesystem.
    let mut tmp = dest.to_path_buf();
    let mut name = dest
        .file_name()
        .unwrap_or_default()
        .to_os_string();
    // Use PID + thread-id to avoid collisions between concurrent writers.
    name.push(format!(
        ".tmp.{}.{}",
        std::process::id(),
        thread_id()
    ));
    tmp.set_file_name(name);

    fs::write(&tmp, data)
        .with_context(|| format!("Failed to write temp file {:?}", tmp))?;
    fs::rename(&tmp, dest)
        .with_context(|| format!("Failed to rename {:?} -> {:?}", tmp, dest))?;
    Ok(())
}

/// Return a cheap numeric id that is unique per thread (stable for the
/// thread's lifetime).  This avoids pulling in an external crate.
fn thread_id() -> u64 {
    // ThreadId doesn't expose a numeric value via a stable API, but its Debug
    // output is "ThreadId(N)".  Parsing is the simplest portable approach.
    let id = std::thread::current().id();
    let dbg = format!("{:?}", id);
    dbg.trim_start_matches("ThreadId(")
        .trim_end_matches(')')
        .parse::<u64>()
        .unwrap_or(0)
}

