    }

    /// Store content and return a cache entry.
    ///
    /// Writes are atomic (write-to-temp + rename) so that concurrent readers
    /// never observe a partially-written content or metadata file.
    pub fn store(
        &self,
        source_id: &str,
        template_name: &str,
        content: &str,
        ttl_seconds: u64,
